import base64,hashlib,json
from pathlib import Path
p=Path('/project/community/jjyeung/ae27b6409c13f')
assets={'0.py': '', '1.json': '', '2.py': '', 'BATCH.sh': 'IyEvYmluL2Jhc2gKc2V0IC1ldW8gcGlwZWZhaWwKdW1hc2sgMDc3CmV4ZWMgL3Vzci9iaW4vcHl0aG9uMyAtSSAtcyAtQiAvcHJvamVjdC9jb21tdW5pdHkvamp5ZXVuZy9hZTI3YjY0MDljMTNmLzAucHkgMSAvcHJvamVjdC9jb21tdW5pdHkvamp5ZXVuZy9hZTI3YjY0MDljMTNmCg==', '3.json': ''}
data={k:base64.b64decode(v) for k,v in assets.items()}
if sum(map(len,data.values()))>=2_000_000:raise ValueError('E40')
pins=json.loads(data['3.json'])
for n,h in pins.items():
